                reader.ThrowIfNotEmpty();
            }
            reader.ThrowIfNotEmpty();
            return value;
        }
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.Sequence;
}

public sealed class TeletexDomainDefinedAttribute : IAsn1Encodable
{
    /// <summary>ASN.1 SIZE (1..8). Not enforced by runtime.</summary>
    public string Type { get; set; } = "";
    /// <summary>ASN.1 SIZE (1..128). Not enforced by runtime.</summary>
    public string Value { get; set; } = "";

    public void Encode(Asn1Writer writer) => Encode(writer, DefaultTag);

    public void Encode(Asn1Writer writer, Asn1Tag tag)
    {
        using (writer.EnterSequence(tag))
        {
            writer.WriteString(Asn1Tag.TeletexString, Type, Asn1StringForm.Teletex);
            writer.WriteString(Asn1Tag.TeletexString, Value, Asn1StringForm.Teletex);
        }
    }

    public static TeletexDomainDefinedAttribute Decode(Asn1Reader reader) => Decode(reader, DefaultTag);

    public static TeletexDomainDefinedAttribute Decode(Asn1Reader reader, Asn1Tag tag)
    {
        using (reader.EnterSequence(tag))
        {
            var value = new TeletexDomainDefinedAttribute();
            value.Type = reader.ReadString(Asn1Tag.TeletexString, Asn1StringForm.Teletex);
            value.Value = reader.ReadString(Asn1Tag.TeletexString, Asn1StringForm.Teletex);
            reader.ThrowIfNotEmpty();
            return value;
        }
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.Sequence;
}

